const state={mode:"local",page:"explore",videos:[],currentVideo:null,lastPage:"library",activity:[]};
const DB_NAME="astralworld-library",DB_VERSION=2;
let dbPromise=null,lastProgressWrite=0,libraryReady=Promise.resolve(),subtitleFontName="Fuente predeterminada";
const coverObjectUrls=new Map();let seekFeedbackTimer=null,lastGestureTap={time:0,side:""};let ambientEnabled=false,ambientFrame=0,ambientLastDraw=0,atmosphereEnabled=false,atmosphereFrame=0,atmosphereLastDraw=0,currentTheme="astral";
const themeNames={astral:"AstralWorld",cosmic:"Cosmic",ocean:"Océano",sunset:"Atardecer",rose:"Rosa lunar"};
function applyTheme(){document.documentElement.dataset.theme=currentTheme;document.documentElement.style.colorScheme="dark";}
function openDB(){if(!("indexedDB"in window))return Promise.reject(new Error("Almacenamiento local no disponible."));if(!dbPromise)dbPromise=new Promise((resolve,reject)=>{const req=indexedDB.open(DB_NAME,DB_VERSION);req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains("videos"))db.createObjectStore("videos",{keyPath:"id"});if(!db.objectStoreNames.contains("activity"))db.createObjectStore("activity",{keyPath:"id"});if(!db.objectStoreNames.contains("fonts"))db.createObjectStore("fonts",{keyPath:"id"});};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});return dbPromise;}
async function storeRecord(store,value){const db=await openDB();return new Promise((resolve,reject)=>{const tx=db.transaction(store,"readwrite");tx.objectStore(store).put(value);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}
async function readRecords(store){const db=await openDB();return new Promise((resolve,reject)=>{const req=db.transaction(store,"readonly").objectStore(store).getAll();req.onsuccess=()=>resolve(req.result||[]);req.onerror=()=>reject(req.error);});}
async function storeActivityLimited(item=null){const db=await openDB();return new Promise((resolve,reject)=>{const tx=db.transaction("activity","readwrite");const store=tx.objectStore("activity");if(item)store.put(item);const req=store.getAll();req.onsuccess=()=>{const ordered=req.result.sort((a,b)=>(b.timestamp||0)-(a.timestamp||0));for(const old of ordered.slice(100))store.delete(old.id);};req.onerror=()=>{try{tx.abort();}catch(error){}};tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error("No se pudo actualizar el historial."));});}
async function saveVideo(v){return storeRecord("videos",{id:v.id,name:v.name,creator:v.creator||"",fileName:v.fileName||v.file?.name||"",relativePath:v.relativePath||"",duration:v.duration||0,file:v.file,cover:v.cover||null,lastModified:v.lastModified||0,size:v.size||v.file?.size||0,mimeType:v.mimeType||v.file?.type||"",width:v.width||0,height:v.height||0,resolution:v.resolution||"",progress:v.progress||0,watched:!!v.watched,lastPlayedAt:v.lastPlayedAt||0,addedAt:v.addedAt||Date.now()});}
async function logActivity(type,v,extra={}){const timestamp=Date.now();const duplicate=state.activity.find(x=>x.type===type&&x.videoId===v.id&&timestamp-(x.timestamp||0)<120000);if(duplicate){duplicate.timestamp=timestamp;Object.assign(duplicate,extra);try{await storeActivityLimited(duplicate);}catch(err){console.warn(err);}if(state.page==="activity")render();return;}const uniqueId=globalThis.crypto?.randomUUID?globalThis.crypto.randomUUID():timestamp+"-"+Math.random().toString(36).slice(2);const item={id:"activity-"+uniqueId,type,videoId:v.id,name:v.name,timestamp,...extra};state.activity.unshift(item);state.activity=state.activity.slice(0,100);try{await storeActivityLimited(item);}catch(err){console.warn(err);}if(state.page==="activity")render();}
async function restoreLibrary(){try{const [videos,activity,fonts]=await Promise.all([readRecords("videos"),readRecords("activity"),readRecords("fonts")]);const savedFont=fonts.find(item=>item.id==="subtitle-font");if(savedFont)await applySubtitleFont(savedFont);state.videos=videos.filter(v=>v.file).map(v=>({...v,name:/^[\d\s._-]+$/.test(v.name||"")?"Vídeo sin título":v.name,creator:v.creator||"",fileName:v.fileName||v.file.name||"",mimeType:v.mimeType||v.file.type||"",width:v.width||0,height:v.height||0,resolution:v.resolution||(v.width&&v.height?v.width+" × "+v.height:""),progress:v.progress||0,watched:!!v.watched,lastPlayedAt:v.lastPlayedAt||0}));const seenActivity=new Set();state.activity=activity.sort((x,y)=>y.timestamp-x.timestamp).filter(x=>{const key=x.type+"|"+x.videoId+"|"+Math.floor((x.timestamp||0)/120000);if(seenActivity.has(key))return false;seenActivity.add(key);return true;}).slice(0,100);if(activity.length>state.activity.length)await storeActivityLimited();render();}catch(err){console.warn("No se pudo recuperar la biblioteca",err);}}
function formatDate(ts){return ts?new Intl.DateTimeFormat("es-MX",{day:"numeric",month:"short",hour:"2-digit",minute:"2-digit"}).format(new Date(ts)):"Sin actividad";}
function isVideoFile(file){return !!file&&((file.type||"").startsWith("video/")||/\.(mp4|m4v|mov|webm|mkv|avi|3gp|ogv)$/i.test(file.name||""));}
function readableTitle(filename){const title=String(filename||"").replace(/\.[^.]+$/,"").replace(/[_]+/g," ").trim();return !title||/^[\d\s._-]+$/.test(title)?"Vídeo sin título":title;}
async function importFiles(fileList){await libraryReady;const files=Array.from(fileList||[]).map(entry=>entry&&entry.file?entry:{file:entry,relativePath:entry?.webkitRelativePath||entry?.name||""}).filter(entry=>isVideoFile(entry.file));let added=0,failed=0,quotaExceeded=false;for(const entry of files){const file=entry.file;const relativePath=entry.relativePath||file.webkitRelativePath||file.name;const identityPath=typeof relativePath.normalize==="function"?relativePath.normalize("NFC"):relativePath;const id=encodeURIComponent(identityPath)+"-"+file.size+"-"+file.lastModified;if(state.videos.some(v=>v.id===id))continue;const item={id,name:readableTitle(file.name),creator:"",fileName:file.name,relativePath,file,duration:0,mimeType:file.type||"",width:0,height:0,resolution:"",progress:0,lastPlayedAt:0,lastModified:file.lastModified,size:file.size,addedAt:Date.now()};state.videos.push(item);try{await saveVideo(item);added++;}catch(err){failed++;quotaExceeded=quotaExceeded||err?.name==="QuotaExceededError"||err?.code===22;console.warn("No se pudo guardar el archivo",err);state.videos=state.videos.filter(v=>v.id!==id);continue;}const probe=document.createElement("video");probe.preload="metadata";probe.onloadedmetadata=async()=>{item.duration=Number.isFinite(probe.duration)?probe.duration:0;item.width=probe.videoWidth||0;item.height=probe.videoHeight||0;item.resolution=item.width&&item.height?item.width+" × "+item.height:"";item.mimeType=file.type||item.mimeType||"";URL.revokeObjectURL(probe.src);try{await saveVideo(item);}catch(err){console.warn("No se pudieron guardar los metadatos",err);}if(state.page!=="player")render();};probe.onerror=()=>URL.revokeObjectURL(probe.src);probe.src=URL.createObjectURL(file);await logActivity("import",item);}if(added)render();if(failed)alert(quotaExceeded?"El almacenamiento del dispositivo está lleno o no tiene espacio suficiente. Libera espacio e intenta importar los vídeos restantes.":"No se pudieron guardar "+failed+" archivo(s). Comprueba que los archivos sigan disponibles e inténtalo de nuevo.");return added;}
