function esc(s){return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));}
function time(s){if(!Number.isFinite(s))return"0:00";const n=Math.floor(s),h=Math.floor(n/3600),m=Math.floor(n%3600/60),r=n%60;return h?h+":"+String(m).padStart(2,"0")+":"+String(r).padStart(2,"0"):m+":"+String(r).padStart(2,"0");}
function kind(v){return v.duration>5400?"Película":"Vídeo";}
function empty(icon,title,desc,extra=""){return '<div class="empty-state"><div class="empty-icon">'+icon+'</div><strong>'+title+'</strong><p>'+desc+'</p>'+extra+'</div>';}
function coverUrl(v){if(!v?.cover)return "";const cached=coverObjectUrls.get(v.id);if(cached?.blob===v.cover)return cached.url;if(cached)URL.revokeObjectURL(cached.url);const url=URL.createObjectURL(v.cover);coverObjectUrls.set(v.id,{blob:v.cover,url});return url;}
function coverMarkup(v,cls=""){const url=coverUrl(v);return url?'<img class="'+cls+'" src="'+url+'" alt="" loading="lazy">':"";}
function list(items){return '<div class="media-list">'+items.map(v=>'<article class="media-row"><button class="media-open" data-video="'+v.id+'" type="button"><span class="media-thumb">'+coverMarkup(v,"media-cover")+svgVideo+'</span><span class="media-copy"><span class="tag">'+(v.watched?"VISTO":kind(v))+'</span><strong>'+esc(v.name)+'</strong><small>'+time(v.duration)+' · '+(v.progress>5?"Progreso guardado":"Archivo local")+'</small></span></button><button class="media-queue" data-queue-video="'+v.id+'" type="button" aria-label="Añadir '+esc(v.name)+' a la cola" title="Añadir a la cola">＋</button><button class="media-remove" data-remove-video="'+v.id+'" type="button" aria-label="Eliminar '+esc(v.name)+' de AstralWorld" title="Eliminar de AstralWorld">'+svgClose+'</button></article>').join('')+'</div>';}
function explore(){
 const recent=state.videos.slice().sort((a,b)=>(b.lastPlayedAt||b.addedAt||0)-(a.lastPlayedAt||a.addedAt||0)).slice(0,8);
 const cards=recent.length?'<div class="continue-rail">'+recent.map(v=>'<button class="continue-card" data-video="'+v.id+'" type="button"><span class="continue-art">'+coverMarkup(v,"continue-cover")+'<span class="continue-play">'+svgPlay+'</span><span class="continue-progress"><i style="width:'+Math.max(0,Math.min(100,(v.progress||0)/(v.duration||1)*100))+'%"></i></span></span><span class="continue-copy"><strong>'+esc(v.name)+'</strong><small>'+time(v.duration)+' · '+(v.progress>0?"Continuar viendo":"Sin reproducir")+'</small></span></button>').join("")+'</div>':empty(svgPlay,"Tu colección empieza aquí","Añade vídeos desde tu dispositivo y aparecerán en este espacio.",'<button class="primary-button" data-action="add" type="button">'+svgAdd+' Añadir vídeos</button>');
 const activityPreview=state.activity.slice(0,3).map(x=>'<div class="activity-row"><span class="activity-dot"></span><div><strong>'+esc(x.name)+'</strong><small>'+(x.type==="play"?"Reproducido":"Añadido")+' · '+formatDate(x.timestamp)+'</small></div></div>').join("");
 return '<section class="welcome-strip"><div><span class="eyebrow">TU ESPACIO PERSONAL</span><h1>Tu universo<br><em>audiovisual.</em></h1><p>Tu biblioteca conserva el progreso de cada vídeo.</p></div><button class="welcome-add" data-action="add" type="button" aria-label="Añadir vídeos">'+svgAdd+'</button></section><section class="quick-library"><div><span class="quick-library-icon">'+svgLibrary+'</span><div><strong>Tu biblioteca</strong><small>'+state.videos.length+' archivos guardados en este dispositivo</small></div></div><button data-page="library" type="button" aria-label="Abrir biblioteca">'+svgArrowUpRight+'</button></section><div class="section-head"><div><span class="eyebrow">LO ÚLTIMO</span><h2>Actividad reciente</h2></div><button class="text-button" data-page="activity" type="button">Ver todo '+svgArrowRight+'</button></div><section class="activity-preview">'+(activityPreview||'<p class="activity-empty">Aquí aparecerán tus reproducciones y archivos añadidos.</p>')+'</section><div class="home-bottom-space"></div>';
}
function library(){return '<span class="eyebrow">TU COLECCIÓN PERSONAL</span><h1>Biblioteca</h1><p class="page-intro">Tus películas y vídeos, reunidos en un solo lugar.</p><div class="library-toolbar"><input class="search-field" id="librarySearch" type="search" placeholder="Buscar en tu biblioteca" aria-label="Buscar en tu biblioteca"><button class="icon-button" data-action="collections" type="button" aria-label="Colecciones personales">▤</button><button class="icon-button" data-action="folder" type="button" aria-label="Leer carpeta">'+svgFolder+'</button><button class="icon-button" data-action="add" type="button" aria-label="Añadir vídeos">'+svgAdd+'</button></div><div class="section-head"><h2>Todo el contenido</h2><span class="tag">'+state.videos.length+' archivos</span></div><div id="libraryResults">'+(state.videos.length?list(state.videos.slice().reverse()):empty(svgLibrary,"Tu biblioteca está vacía","Añade archivos de vídeo desde tu dispositivo para empezar.",'<button class="primary-button" data-action="add" type="button">'+svgAdd+' Añadir vídeos</button>'))+'</div>';}
function activityPage(){const seen=new Set();const clean=state.activity.filter(x=>{const key=x.type+"|"+x.videoId+"|"+Math.floor((x.timestamp||0)/120000);if(seen.has(key))return false;seen.add(key);return true;});const rows=clean.map(x=>'<article class="activity-entry"><span class="activity-entry-icon">'+(x.type==="play"?svgPlay:svgAdd)+'</span><div class="activity-entry-copy"><strong>'+esc(x.name)+'</strong><small>'+(x.type==="play"?"Reproducción":"Importación")+(x.position!=null?" · Desde "+time(x.position):"")+'</small><time>'+formatDate(x.timestamp)+'</time></div><span class="activity-entry-tag">'+(x.type==="play"?"VISTO":"AÑADIDO")+'</span></article>').join("");return '<button class="text-button activity-back" data-page="explore" type="button">'+svgArrowLeft+' Volver</button><span class="eyebrow">TU HISTORIAL PERSONAL</span><h1>Actividad reciente</h1><p class="page-intro">Tus últimas reproducciones e importaciones, sin registros repetidos.</p><section class="activity-list">'+(rows||'<p class="activity-empty">Todavía no hay actividad. Cuando añadas o reproduzcas vídeos, aparecerán aquí.</p>')+'</section>';}

function settings(){return '<span class="eyebrow">PREFERENCIAS</span><h1>Ajustes</h1><p class="page-intro">Configura cómo se ve y se comporta AstralWorld.</p><section class="settings-group"><h2>Experiencia</h2><div class="setting-row"><div><strong>Modo de app</strong><p>Cambia entre contenido local y online.</p></div><span class="tag">'+(state.mode==="local"?"Local":"Online")+'</span></div><div class="mode-switch"><button class="mode-button '+(state.mode==="local"?"active":"")+'" data-mode="local" type="button">Local</button><button class="mode-button '+(state.mode==="online"?"active":"")+'" data-mode="online" type="button">Online</button></div></section><section class="settings-group"><h2>Temas de color</h2><p class="settings-hint">Elige la atmósfera visual de AstralWorld. Se guarda automáticamente.</p><div class="theme-grid">'+Object.entries(themeNames).map(([id,name])=>'<button class="theme-choice '+(currentTheme===id?"active":"")+'" data-theme-select="'+id+'" type="button" aria-pressed="'+(currentTheme===id)+'"><span class="theme-preview theme-'+id+'"></span><strong>'+name+'</strong><span class="theme-check">✓</span></button>').join("")+'</div><div class="setting-row"><div><strong>Ambient Light</strong><p>Ilumina suavemente el fondo con los colores del vídeo.</p></div><button class="setting-toggle '+(ambientEnabled?"active":"")+'" data-action="ambient" type="button" role="switch" aria-checked="'+ambientEnabled+'"><span></span></button></div><div class="setting-row"><div><strong>Video Atmosphere</strong><p>Expande y difumina los colores del vídeo detrás de la imagen. Efecto independiente.</p></div><button class="setting-toggle '+(atmosphereEnabled?"active":"")+'" data-action="atmosphere" type="button" role="switch" aria-checked="'+atmosphereEnabled+'"><span></span></button></div></section><section class="settings-group"><h2>Tipografía de subtítulos</h2><p class="settings-hint">Importa una fuente propia para personalizar los subtítulos del reproductor.</p><div class="font-import-row"><div><strong id="subtitleFontName">'+esc(subtitleFontName)+'</strong><small>TTF, OTF, WOFF o WOFF2</small></div><button class="secondary-button" data-action="font" type="button">Importar fuente</button></div><button class="text-button font-reset" data-action="resetFont" type="button">Restablecer fuente</button></section><section class="settings-group"><h2>Reproducción</h2><div class="setting-row"><div><strong>Gestos de búsqueda</strong><p>Doble toque a la izquierda o derecha para saltar 10 segundos.</p></div><span class="tag">10 s</span></div><div class="setting-row"><div><strong>Pantalla cinematográfica</strong><p>El reproductor solicita pantalla completa y orientación horizontal cuando el dispositivo lo permite.</p></div></div></section><section class="settings-group"><h2>Instalación</h2><div class="setting-row"><div><strong>Instalar AstralWorld</strong><p>Añade la aplicación a tu pantalla de inicio.</p></div><button class="secondary-button" data-action="install" type="button">Instalar</button></div></section><section class="settings-group"><h2>Acerca de</h2><div class="setting-row"><div><strong>AstralWorld</strong><p>Tu espacio personal para vídeos y películas.</p></div><span class="tag">En desarrollo</span></div></section>';}
function online(){return '<section class="online-hero"><span class="eyebrow">ASTRALWORLD · ONLINE</span><h1>Hay más<br><em>por descubrir.</em></h1><p>Un nuevo espacio para explorar historias y encontrar algo que ver.</p><span class="online-hero-mark">✧</span></section><div class="online-heading"><span class="eyebrow">EXPLORA EL UNIVERSO</span><h2>Descubrimiento</h2><p>Próximamente, recomendaciones y contenido seleccionado.</p></div><div class="online-editorial"><article class="editorial-tile editorial-wide"><span class="editorial-art editorial-art-one">✦</span><div><small>PRÓXIMAMENTE</small><strong>Selecciones para ti</strong><p>Historias que podrían interesarte.</p></div></article><article class="editorial-tile"><span class="editorial-art editorial-art-two">◌</span><div><small>EXPLORA</small><strong>Nuevos universos</strong></div></article><article class="editorial-tile"><span class="editorial-art editorial-art-three">✧</span><div><small>COLECCIONES</small><strong>Por descubrir</strong></div></article></div><div class="online-note">La experiencia Online está en desarrollo. Sus funciones llegarán en próximas versiones.</div>';}
function profile(){return '<span class="eyebrow">TU ESPACIO ASTRAL</span><h1>Perfil</h1><section class="profile-card"><div class="profile-avatar">✧</div><strong>Mi espacio</strong><small>Tu experiencia en AstralWorld</small></section><div class="section-head"><h2>Tu actividad</h2></div><div class="profile-stat-row"><div><strong>'+state.videos.length+'</strong><small>Archivos locales</small></div><div><strong>—</strong><small>Favoritos</small></div><div><strong>—</strong><small>Listas</small></div></div><div class="online-note">El perfil Online tendrá opciones de cuenta y personalización cuando se desarrollen sus funciones.</div>';}
function player(){const v=state.currentVideo;return '<section class="player-page" id="playerPage"><div class="player-topline"><button class="player-back" data-action="back" type="button">'+svgBack+'<span>Volver</span></button><span class="player-kicker">REPRODUCIENDO</span><button class="player-more" data-action="menu" aria-label="Más opciones" type="button">'+svgMore+'</button></div><div class="video-stage" id="videoStage"><canvas class="video-atmosphere-canvas" id="videoAtmosphereCanvas" aria-hidden="true"></canvas><canvas class="ambient-light-canvas" id="ambientCanvas" aria-hidden="true"></canvas><video id="mainVideo" playsinline preload="metadata"></video><div class="video-placeholder" id="videoPlaceholder"><span class="placeholder-symbol">'+svgPlay+'</span><strong>Preparando reproducción</strong><span>Tu espacio audiovisual</span></div><div class="seek-feedback" id="seekFeedback" aria-live="polite"></div><div class="video-overlay" id="videoOverlay"><div class="video-overlay-center"><button class="skip-control" data-action="seekBack" aria-label="Retroceder 10 segundos" type="button">'+svgBack10+'</button><button class="hero-play-button" data-action="toggle" aria-label="Reproducir o pausar" id="playToggle" type="button">'+svgPlay+'</button><button class="skip-control" data-action="seekForward" aria-label="Adelantar 10 segundos" type="button">'+svgForward10+'</button></div><div class="video-overlay-bottom"><div class="player-control-line"><input id="seekBar" type="range" min="0" max="100" value="0" aria-label="Posición del vídeo"><div class="player-time-row"><span id="currentTime">0:00</span><span id="totalTime">0:00</span></div></div><div class="video-tools"><button id="fullscreenAmbientToggle" class="fullscreen-ambient-toggle" data-action="ambient" aria-label="Activar Ambient light" aria-pressed="'+(ambientEnabled?'true':'false')+'" type="button">'+svgSpeed+'</button><button id="fullscreenToggle" data-action="expand" aria-label="Pantalla completa" type="button">'+svgExpand+'</button><button class="fullscreen-exit" data-action="exitFullscreen" aria-label="Salir de pantalla completa" type="button">'+svgExitFullscreen+'</button></div></div></div></div><div class="player-heading"><div class="player-title-copy"><h1>'+esc(v.name)+'</h1><p class="player-meta">'+esc(v.creator||"Archivo local")+' <span>·</span> '+time(v.duration)+'</p></div><button class="player-edit-button" data-action="editInfo" type="button" aria-label="Editar información">'+svgEdit+'</button></div><div class="player-primary-actions"><button class="player-action" data-action="speed" type="button"><span class="action-icon">'+svgSpeed+'</span><span class="speed-label">1×</span></button><button class="player-action" data-action="ambient" type="button"><span class="action-icon">'+svgSpeed+'</span><span>Ambient light</span><i class="ambient-state">'+(ambientEnabled?"Activado":"Desactivado")+'</i></button><button class="player-action" data-action="subtitles" type="button"><span class="action-icon">'+svgCaptions+'</span><span>Subtítulos</span></button><button class="player-action" data-action="audioMode" type="button"><span class="action-icon">'+svgAudio+'</span><span>Modo de audio</span><i class="audio-mode-state">'+({standard:"Estándar",music:"Música",theater:"Teatro"}[audioMode]||"Estándar")+'</i></button><button class="player-action" data-action="lock" type="button"><span class="action-icon">◈</span><span>Bloquear pantalla</span></button><button class="player-action" data-action="screenshot" type="button"><span class="action-icon">'+svgImage+'</span><span>Capturar fotograma</span></button><button class="player-action" data-action="subtitleStyle" type="button"><span class="action-icon">Aa</span><span>Estilo de subtítulos</span></button><button class="player-action" data-action="playbackMode" type="button"><span class="action-icon">↻</span><span>Modo de reproducción</span></button></div><details class="player-info"><summary>Información del vídeo</summary><div class="info-line"><span>Archivo original</span><strong>'+esc(v.fileName||v.file?.name||"No disponible")+'</strong></div><div class="info-line"><span>Formato</span><strong>'+kind(v)+'</strong></div><div class="info-line"><span>Ubicación</span><strong>Este dispositivo</strong></div></details></section>';}
function renderMiniPlayer(){const existing=document.getElementById("miniPlayer");if(!state.currentVideo||!persistentVideo||!persistentVideo.src){existing?.remove();return;}if(existing){const title=existing.querySelector(".mini-info strong");if(title)title.textContent=state.currentVideo.name;syncPlayIcons();return;}const mini=document.createElement("aside");mini.id="miniPlayer";mini.className="mini-player";mini.innerHTML='<div class="mini-video-slot" id="miniVideoSlot"></div><button class="mini-info" type="button" aria-label="Volver al reproductor"><strong>'+esc(state.currentVideo.name)+'</strong><small>Reproduciendo · AstralWorld</small></button><button class="mini-control mini-expand" data-mini="expand" type="button" aria-label="Abrir reproductor">'+svgExpand+'</button><button class="mini-control" id="miniPlay" data-mini="toggle" type="button" aria-label="Pausar">'+svgPause+'</button><button class="mini-control mini-close" data-mini="close" type="button" aria-label="Cerrar mini reproductor">'+svgClose+'</button>';document.body.appendChild(mini);mini.querySelector("#miniVideoSlot").appendChild(persistentVideo);ensureMiniEffects(mini);persistentVideo.muted=false;mini.querySelector(".mini-info").addEventListener("click",()=>{state.page="player";render();});mini.querySelector('[data-mini="expand"]').addEventListener("click",()=>{state.page="player";render();});mini.querySelector('[data-mini="toggle"]').addEventListener("click",()=>{if(persistentVideo.paused)persistentVideo.play().catch(()=>{});else persistentVideo.pause();syncPlayIcons();});mini.querySelector('[data-mini="close"]').addEventListener("click",()=>act("closeMini"));syncPlayIcons();}
function pageRank(page){const ranks={explore:0,home:0,library:1,profile:1,activity:1,settings:2,player:3};return Object.prototype.hasOwnProperty.call(ranks,page)?ranks[page]:null;}
function render(){const pages={explore,library,settings,home:online,profile,player,activity:activityPage};if(!pages[state.page])state.page="explore";const previousPage=lastRenderedPage;const previousRank=pageRank(previousPage),nextRank=pageRank(state.page);const direction=previousRank===null||nextRank===null||previousRank===nextRank?1:(nextRank>previousRank?1:-1);document.documentElement.style.setProperty("--screen-direction",String(direction));document.documentElement.style.setProperty("--screen-enter-x",direction>0?"28px":"-28px");document.documentElement.style.setProperty("--screen-exit-x",direction>0?"-16px":"16px");const pageChanged=previousPage!==state.page;const update=()=>{if(state.page!=="player"){const current=document.getElementById("mainVideo");if(current)persistentVideo=current;}content.innerHTML=pages[state.page]();const topbar=document.querySelector(".topbar");if(topbar)topbar.hidden=state.page!=="explore";content.classList.remove("page-enter");if(!document.startViewTransition||window.matchMedia("(prefers-reduced-motion: reduce)").matches)content.classList.add("page-enter");nav.hidden=state.page==="player";nav.innerHTML=navItems[state.mode].map(x=>'<button class="nav-item '+(state.page===x.id?"active":"")+'" data-page="'+x.id+'" type="button" aria-current="'+(state.page===x.id?"page":"false")+'"><span class="nav-icon">'+navIcons[x.id]+'</span><span class="nav-label">'+x.label+'</span></button>').join("");bind();if(state.page==="player"){const mini=document.getElementById("miniPlayer");if(mini){mini.classList.add("is-closing");setTimeout(()=>mini.remove(),230);}setupPlayer();}else renderMiniPlayer();};if(pageChanged&&previousPage!==null&&document.startViewTransition&&!window.matchMedia("(prefers-reduced-motion: reduce)").matches){document.startViewTransition(update);}else update();lastRenderedPage=state.page;}
function go(page){if(state.page==="player"&&page!=="player"&&document.fullscreenElement)document.exitFullscreen().catch(()=>{});state.page=page;render();}
function bind(){content.querySelectorAll("[data-page]").forEach(b=>b.addEventListener("click",()=>go(b.dataset.page)));nav.querySelectorAll("[data-page]").forEach(b=>b.addEventListener("click",()=>go(b.dataset.page)));content.querySelectorAll("[data-mode]").forEach(b=>b.addEventListener("click",()=>{state.mode=b.dataset.mode;state.page=state.mode==="local"?"explore":"home";render();}));content.querySelectorAll("[data-theme-select]").forEach(b=>b.addEventListener("click",()=>{currentTheme=b.dataset.themeSelect;try{localStorage.setItem("astralworld-theme",currentTheme);}catch(error){}applyTheme();render();}));content.querySelectorAll("[data-action]").forEach(b=>b.addEventListener("click",()=>act(b.dataset.action)));content.querySelectorAll("[data-video]").forEach(b=>b.addEventListener("click",()=>openVideo(b.dataset.video)));bindLibraryRemove(content);content.querySelectorAll("[data-filter]").forEach(b=>b.addEventListener("click",()=>{go("library");const input=document.getElementById("librarySearch");if(input)input.placeholder="Filtrar películas de más de 90 minutos";}));const search=document.getElementById("librarySearch");if(search)search.addEventListener("input",()=>{const q=search.value.toLocaleLowerCase();const filtered=state.videos.slice().reverse().filter(v=>v.name.toLocaleLowerCase().includes(q));document.getElementById("libraryResults").innerHTML=filtered.length?list(filtered):empty(svgSearch,"No encontramos ese archivo","Prueba con otro nombre.");document.querySelectorAll("#libraryResults [data-video]").forEach(b=>b.addEventListener("click",()=>openVideo(b.dataset.video)));bindLibraryRemove(document.getElementById("libraryResults"));});}
function openVideo(id){const v=state.videos.find(x=>x.id===id);if(!v)return;state.currentVideo=v;state.lastPage=state.page;v.lastPlayedAt=Date.now();saveVideo(v).catch(console.warn);logActivity("play",v,{position:v.progress||0});state.page="player";render();}
function seekBy(seconds){const video=persistentVideo;if(!video||!Number.isFinite(video.duration))return;video.currentTime=Math.max(0,Math.min(video.duration,video.currentTime+seconds));showSeekFeedback(seconds);showOverlay();}
function showSeekFeedback(seconds){const stage=document.getElementById("videoStage"),feedback=document.getElementById("seekFeedback");if(!stage||!feedback)return;feedback.className="seek-feedback "+(seconds<0?"rewind":"forward");feedback.innerHTML=(seconds<0?svgBack10:svgForward10)+'<strong>'+(seconds<0?"−10":"＋10")+"</strong>";clearTimeout(seekFeedbackTimer);requestAnimationFrame(()=>feedback.classList.add("visible"));seekFeedbackTimer=setTimeout(()=>feedback.classList.remove("visible"),720);}
function updateSeekBar(bar,value){if(!bar)return;const progress=Math.max(0,Math.min(100,Number(value)||0));bar.value=progress;bar.style.setProperty("--seek-progress",progress+"%");}

function initializeAudioEngine(video){
 if(!video||audioSource)return;
 const AudioContextClass=window.AudioContext||window.webkitAudioContext;
 if(!AudioContextClass)return;
 try{
  audioContext=new AudioContextClass();
  audioSource=audioContext.createMediaElementSource(video);
  const low=audioContext.createBiquadFilter();low.type="lowshelf";low.frequency.value=110;
  const mid=audioContext.createBiquadFilter();mid.type="peaking";mid.frequency.value=2800;mid.Q.value=.85;
  const high=audioContext.createBiquadFilter();high.type="highshelf";high.frequency.value=8500;
  const compressor=audioContext.createDynamicsCompressor();
  audioSource.connect(low);low.connect(mid);mid.connect(high);high.connect(compressor);compressor.connect(audioContext.destination);
  audioNodes={low,mid,high,compressor};applyAudioMode(audioMode,false);
 }catch(error){console.warn("Procesamiento de audio no disponible; se conserva el sonido original.",error);audioContext=null;audioSource=null;audioNodes=null;}
}
function resumeAudioContext(){if(audioContext&&audioContext.state!=="running")audioContext.resume().catch(error=>console.warn("No se pudo activar el audio",error));}
function applyAudioMode(mode,save=true){
 const allowed=["standard","music","theater"];audioMode=allowed.includes(mode)?mode:"standard";
 if(save){try{localStorage.setItem("astralworld-audio-mode",audioMode);}catch(error){}}
 if(audioNodes&&audioContext){
  const profiles={standard:{low:0,mid:0,high:0,threshold:0,ratio:1},music:{low:4.5,mid:1.8,high:2.2,threshold:-19,ratio:2.1},theater:{low:2.5,mid:2.8,high:3.4,threshold:-16,ratio:1.7}};
  const p=profiles[audioMode],now=audioContext.currentTime;
  audioNodes.low.gain.setTargetAtTime(p.low,now,.08);audioNodes.mid.gain.setTargetAtTime(p.mid,now,.08);audioNodes.high.gain.setTargetAtTime(p.high,now,.08);
  audioNodes.compressor.threshold.setTargetAtTime(p.threshold,now,.08);audioNodes.compressor.ratio.setTargetAtTime(p.ratio,now,.08);
 }
 const label={standard:"Estándar",music:"Música",theater:"Teatro"}[audioMode];
 document.querySelectorAll(".audio-mode-state").forEach(el=>el.textContent=label);
 document.querySelectorAll("[data-audio-mode]").forEach(btn=>{const active=btn.dataset.audioMode===audioMode;btn.classList.toggle("active",active);btn.setAttribute("aria-pressed",String(active));});
}
