function applyAmbientLight(){document.documentElement.classList.toggle("ambient-enabled",ambientEnabled);const mini=document.getElementById("miniPlayer");if(mini)ensureMiniEffects(mini);const stage=document.getElementById("videoStage");if(stage&&ambientEnabled){ensureAmbientCanvas(stage);stage.querySelector("#ambientCanvas")?.classList.add("is-active");}else stage?.querySelector("#ambientCanvas")?.classList.remove("is-active");if(!ambientEnabled&&ambientFrame){cancelAnimationFrame(ambientFrame);ambientFrame=0;}if(stage&&atmosphereEnabled){ensureVideoAtmosphere(stage);stage.querySelector("#videoAtmosphereCanvas")?.classList.add("is-active");}else stage?.querySelector("#videoAtmosphereCanvas")?.classList.remove("is-active");if(!atmosphereEnabled&&atmosphereFrame){cancelAnimationFrame(atmosphereFrame);atmosphereFrame=0;}if(!atmosphereEnabled&&stage){stage.classList.remove("video-atmosphere-on");stage.style.removeProperty("--atmosphere-glow");}}
