function closePlayerMenu(menu){if(!menu||menu.classList.contains("is-closing"))return;menu.classList.add("is-closing");setTimeout(()=>menu.remove(),180);}
function showPlayerMenu(){document.getElementById("playerActionMenu")?.remove();const menu=document.createElement("div");menu.id="playerActionMenu";menu.className="player-action-menu";menu.innerHTML='<button type="button" data-menu-action="edit">'+svgEdit+' <span>Editar información</span></button><button type="button" data-menu-action="remove">'+svgClose+' <span>Eliminar de AstralWorld</span></button><button type="button" data-menu-action="close">'+svgClose+' <span>Cerrar</span></button>';document.body.appendChild(menu);menu.querySelector('[data-menu-action="edit"]').addEventListener("click",()=>{closePlayerMenu(menu);setTimeout(editCurrentInfo,120);});menu.querySelector('[data-menu-action="remove"]').addEventListener("click",()=>{closePlayerMenu(menu);setTimeout(()=>deleteVideoFromLibrary(state.currentVideo?.id),120);});menu.querySelector('[data-menu-action="close"]').addEventListener("click",()=>closePlayerMenu(menu));document.addEventListener("pointerdown",function outside(event){if(!menu.contains(event.target)){closePlayerMenu(menu);document.removeEventListener("pointerdown",outside);}});}
function editCurrentInfo(){const v=state.currentVideo;if(!v)return;document.getElementById("editInfoDialog")?.remove();const dialog=document.createElement("dialog");dialog.id="editInfoDialog";dialog.className="edit-info-dialog";dialog.innerHTML='<form method="dialog" class="edit-info-form"><span class="eyebrow">TU BIBLIOTECA</span><h2>Editar información</h2><label class="cover-edit-label">Portada del vídeo<span class="cover-edit-preview">'+(v.cover?'<img src="'+coverUrl(v)+'" alt="Portada actual">':'<span>'+svgVideo+'</span>')+'</span><input name="cover" type="file" accept="image/*"><small>Elige una imagen de tu dispositivo.</small></label><label>Nombre<input name="title" maxlength="120" required></label><label>Creador o canal<input name="creator" maxlength="100" placeholder="Nombre del creador o canal"></label><div class="edit-info-actions"><button type="button" class="secondary-button" data-cancel>Cancelar</button><button type="submit" class="primary-button">Guardar cambios</button></div></form>';document.body.appendChild(dialog);dialog.querySelector('[name="title"]').value=v.name==="Vídeo sin título"?"":v.name;dialog.querySelector('[name="creator"]').value=v.creator||"";const coverInput=dialog.querySelector('[name="cover"]');coverInput.addEventListener("change",()=>{const file=coverInput.files?.[0];if(!file)return;const preview=dialog.querySelector(".cover-edit-preview"),url=URL.createObjectURL(file);preview.innerHTML='<img src="'+url+'" alt="Vista previa de portada">';});dialog.querySelector("[data-cancel]").addEventListener("click",()=>closeEditDialog(dialog));dialog.querySelector("form").addEventListener("submit",async event=>{event.preventDefault();const title=dialog.querySelector('[name="title"]').value.trim();if(!title){dialog.querySelector('[name="title"]').focus();return;}v.name=title;v.creator=dialog.querySelector('[name="creator"]').value.trim();const coverFile=coverInput.files?.[0];if(coverFile&&coverFile.type.startsWith("image/"))v.cover=coverFile;try{await saveVideo(v);const cached=coverObjectUrls.get(v.id);if(cached){URL.revokeObjectURL(cached.url);coverObjectUrls.delete(v.id);}closeEditDialog(dialog);setTimeout(render,190);}catch(error){console.warn("No se pudo guardar la información",error);alert("No se pudo guardar la información. Comprueba el almacenamiento del dispositivo.");}});dialog.addEventListener("click",event=>{if(event.target===dialog)closeEditDialog(dialog);});dialog.addEventListener("cancel",event=>{event.preventDefault();closeEditDialog(dialog);});dialog.showModal();}
function closeEditDialog(dialog){if(!dialog||dialog.classList.contains("is-closing"))return;dialog.classList.add("is-closing");setTimeout(()=>{if(dialog.open)dialog.close();dialog.remove();},180);}

function cyclePlaybackMode(){const modes=["normal","repeat","shuffle"];let mode="normal";try{mode=localStorage.getItem("astralworld-playback-mode")||"normal";}catch(e){}mode=modes[(modes.indexOf(mode)+1)%modes.length];try{localStorage.setItem("astralworld-playback-mode",mode);}catch(e){}const labels={normal:"Normal",repeat:"Repetir",shuffle:"Aleatorio"};const label=document.querySelector('[data-action="playbackMode"] span:last-child');if(label)label.textContent="Modo: "+labels[mode];window.astralPlaybackMode=mode;}
