async function captureFrame(){const video=persistentVideo;if(!video||video.readyState<2||!video.videoWidth){alert("Espera a que el vídeo esté listo.");return;}try{const canvas=document.createElement("canvas");canvas.width=video.videoWidth;canvas.height=video.videoHeight;canvas.getContext("2d").drawImage(video,0,0);const blob=await new Promise(resolve=>canvas.toBlob(resolve,"image/png"));const url=URL.createObjectURL(blob),link=document.createElement("a");link.href=url;link.download="AstralWorld-fotograma.png";link.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}catch(e){alert("No se pudo capturar el fotograma.");}}
