async function deleteVideoFromLibrary(id){const item=state.videos.find(video=>video.id===id);if(!item)return;if(!confirm('¿Eliminar "'+item.name+'" de AstralWorld? El archivo original de tu dispositivo no se borrará.'))return;try{const db=await openDB();await new Promise((resolve,reject)=>{const tx=db.transaction(["videos","activity"],"readwrite");tx.objectStore("videos").delete(id);const activity=tx.objectStore("activity"),req=activity.getAll();req.onsuccess=()=>req.result.filter(entry=>entry.videoId===id).forEach(entry=>activity.delete(entry.id));req.onerror=()=>{try{tx.abort();}catch(error){}};tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error("No se pudo eliminar el registro."));});state.videos=state.videos.filter(video=>video.id!==id);state.activity=state.activity.filter(entry=>entry.videoId!==id);if(state.currentVideo?.id===id){if(persistentVideo){persistentVideo.pause();persistentVideo.removeAttribute("src");persistentVideo.load();persistentVideo.remove();}if(activeUrl)URL.revokeObjectURL(activeUrl);activeUrl=null;persistentVideo=null;state.currentVideo=null;document.getElementById("miniPlayer")?.remove();if(state.page==="player")state.page=state.lastPage||"library";}render();}catch(error){console.warn(error);alert("No se pudo quitar el vídeo de AstralWorld. Inténtalo de nuevo.");}}
function bindLibraryRemove(root){if(!root)return;root.querySelectorAll("[data-remove-video]").forEach(button=>button.addEventListener("click",event=>{event.preventDefault();event.stopPropagation();deleteVideoFromLibrary(button.dataset.removeVideo);}));}
async function applySubtitleFont(record){if(!record?.file)return;try{subtitleFontName=record.name||"Fuente personalizada";if(window.astralSubtitleFontUrl)URL.revokeObjectURL(window.astralSubtitleFontUrl);const url=URL.createObjectURL(record.file);window.astralSubtitleFontUrl=url;const face=new FontFace("AstralCustomSubtitle",'url("'+url+'")');await face.load();document.fonts.add(face);window.astralSubtitleFontFamily="AstralCustomSubtitle";const label=document.getElementById("subtitleFontName");if(label)label.textContent=subtitleFontName;const saved={size:100,color:"#ffffff",bg:65};try{Object.assign(saved,JSON.parse(localStorage.getItem("astralworld-subtitle-style")||"{}"));}catch(error){}applySubtitleStyle(saved);}catch(error){console.warn("No se pudo cargar la fuente personalizada",error);}}
function openFontPicker(){let input=document.getElementById("subtitleFontPicker");if(!input){input=document.createElement("input");input.type="file";input.id="subtitleFontPicker";input.accept=".ttf,.otf,.woff,.woff2,font/ttf,font/otf,font/woff,font/woff2";input.className="visually-hidden";document.body.appendChild(input);}input.onchange=async()=>{const file=input.files?.[0];input.value="";if(!file)return;const ext=(file.name.split(".").pop()||"").toLowerCase();if(!["ttf","otf","woff","woff2"].includes(ext)){alert("Formato no compatible. Usa TTF, OTF, WOFF o WOFF2.");return;}try{const record={id:"subtitle-font",name:file.name,file};await storeRecord("fonts",record);await applySubtitleFont(record);alert("Fuente importada para los subtítulos.");}catch(error){console.warn(error);alert("No se pudo guardar la fuente. Comprueba el espacio disponible.");}};input.click();}
async function resetSubtitleFont(){try{const db=await openDB();await new Promise((resolve,reject)=>{const tx=db.transaction("fonts","readwrite");tx.objectStore("fonts").delete("subtitle-font");tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});if(window.astralSubtitleFontUrl)URL.revokeObjectURL(window.astralSubtitleFontUrl);window.astralSubtitleFontUrl=null;window.astralSubtitleFontFamily=null;const label=document.getElementById("subtitleFontName");subtitleFontName="Fuente predeterminada";if(label)label.textContent=subtitleFontName;const saved={size:100,color:"#ffffff",bg:65};try{Object.assign(saved,JSON.parse(localStorage.getItem("astralworld-subtitle-style")||"{}"));}catch(error){}applySubtitleStyle(saved);}catch(error){alert("No se pudo restablecer la fuente.");}}
function openSubtitleStyle(){let saved={size:100,color:"#ffffff",bg:65};try{saved={...saved,...JSON.parse(localStorage.getItem("astralworld-subtitle-style")||"{}")};}catch(error){}const dialog=document.createElement("dialog");dialog.className="player-choice-dialog subtitle-style-dialog";dialog.innerHTML='<div class="player-choice-head"><span class="eyebrow">REPRODUCTOR</span><h2>Estilo de subtítulos</h2><p>Ajusta su apariencia sin saturar la pantalla.</p></div><div class="subtitle-style-grid"><label class="subtitle-style-control"><span>Tamaño</span><output id="subSizeValue">'+saved.size+'%</output><input id="subSize" type="range" min="70" max="150" value="'+saved.size+'"></label><label class="subtitle-style-control"><span>Color del texto</span><input id="subColor" type="color" value="'+saved.color+'"></label><label class="subtitle-style-control"><span>Opacidad del fondo</span><output id="subBgValue">'+saved.bg+'%</output><input id="subBg" type="range" min="0" max="100" value="'+saved.bg+'"></label></div><div class="subtitle-font-actions"><span>Tipografía personalizada</span><button type="button" class="secondary-button" data-font-import>Importar fuente</button></div><div class="subtitle-dialog-actions"><button type="button" class="secondary-button choice-close">Cancelar</button><button type="button" class="primary-button" data-save>Guardar</button></div>';document.body.appendChild(dialog);dialog.querySelector("#subSize").addEventListener("input",e=>dialog.querySelector("#subSizeValue").textContent=e.target.value+"%");dialog.querySelector("#subBg").addEventListener("input",e=>dialog.querySelector("#subBgValue").textContent=e.target.value+"%");dialog.querySelector("[data-font-import]").addEventListener("click",()=>openFontPicker());dialog.querySelector(".choice-close").addEventListener("click",()=>dialog.close());dialog.querySelector("[data-save]").addEventListener("click",()=>{const settings={size:dialog.querySelector("#subSize").value,color:dialog.querySelector("#subColor").value,bg:dialog.querySelector("#subBg").value};applySubtitleStyle(settings);try{localStorage.setItem("astralworld-subtitle-style",JSON.stringify(settings));}catch(error){}dialog.close();});dialog.addEventListener("close",()=>dialog.remove());dialog.showModal();}
function openSpeedPicker(video){
  document.getElementById("speedPickerDialog")?.remove();
  const rates=[0.25,0.5,0.75,1,1.25,1.5,1.75,2];
  const dialog=document.createElement("dialog");dialog.id="speedPickerDialog";dialog.className="player-choice-dialog";
  dialog.innerHTML='<div class="player-choice-head"><span class="eyebrow">REPRODUCCIÓN</span><h2>Velocidad</h2><p>Selecciona cómo quieres reproducir este vídeo.</p></div><div class="speed-options">'+rates.map(rate=>'<button type="button" class="speed-option'+(video.playbackRate===rate?' active':'')+'" data-rate="'+rate+'" aria-pressed="'+(video.playbackRate===rate)+'"><span>'+rate+'×</span>'+(rate===1?'<small>Normal</small>':'')+'</button>').join("")+'</div><button type="button" class="secondary-button choice-close">Cerrar</button>';
  document.body.appendChild(dialog);
  dialog.querySelectorAll("[data-rate]").forEach(button=>button.addEventListener("click",()=>{video.playbackRate=Number(button.dataset.rate);document.querySelectorAll(".speed-label").forEach(label=>label.textContent=video.playbackRate+"×");dialog.querySelectorAll(".speed-option").forEach(option=>{const active=option===button;option.classList.toggle("active",active);option.setAttribute("aria-pressed",String(active));});}));
  dialog.querySelector(".choice-close").addEventListener("click",()=>dialog.close());
  dialog.addEventListener("close",()=>dialog.remove());dialog.addEventListener("click",event=>{if(event.target===dialog)dialog.close();});dialog.showModal();
}
function openSubtitlePicker(){
  const video=persistentVideo;if(!video)return;
  let input=document.getElementById("subtitleFilePicker");
  if(!input){input=document.createElement("input");input.type="file";input.id="subtitleFilePicker";input.accept=".vtt,.srt,text/vtt,application/x-subrip";input.className="visually-hidden";document.body.appendChild(input);}
  input.onchange=()=>{
    const file=input.files&&input.files[0];input.value="";if(!file)return;
    const ext=(file.name.split(".").pop()||"").toLowerCase();
    if(!["vtt","srt"].includes(ext)){alert("Elige un archivo de subtítulos .VTT o .SRT.");return;}
    const reader=new FileReader();
    reader.onload=()=>{
      try{
        let content=String(reader.result||"").replace(/^\uFEFF/,"");
        if(ext==="srt"){content="WEBVTT\n\n"+content.replace(/(\d{2}:\d{2}:\d{2}),(\d{3})/g,"$1.$2").replace(/^(\d+)\s*$/gm,"");}
        if(!content.trim().startsWith("WEBVTT"))throw new Error("invalid");
        if(activeSubtitleUrl)URL.revokeObjectURL(activeSubtitleUrl);
        activeSubtitleUrl=URL.createObjectURL(new Blob([content],{type:"text/vtt"}));
        video.querySelectorAll("track[data-astral-subtitle]").forEach(track=>track.remove());
        const track=document.createElement("track");track.kind="subtitles";track.label=file.name;track.srclang="es";track.src=activeSubtitleUrl;track.default=true;track.dataset.astralSubtitle="1";video.appendChild(track);
        track.addEventListener("load",()=>{track.track.mode="showing";},{once:true});
        try{track.track.mode="showing";}catch(error){}
        alert("Subtítulos importados: "+file.name);
      }catch(error){alert("No se pudo leer el archivo. Comprueba que sea un .VTT o .SRT válido.");}
    };
    reader.onerror=()=>alert("No se pudo leer el archivo de subtítulos.");
    reader.readAsText(file);
  };
  input.click();
}

function confirmPerformanceEffect(action){const title=action==="ambient"?"Ambient Light":"Video Atmosphere";const dialog=document.createElement("dialog");dialog.className="player-choice-dialog performance-warning";dialog.innerHTML='<div class="player-choice-head"><span class="eyebrow">AVISO DE RENDIMIENTO</span><h2>Activar '+title+'?</h2><p>Este efecto analiza los colores del vídeo y puede aumentar el consumo de recursos, calentar el dispositivo o reducir la fluidez en equipos menos potentes.</p></div><div class="performance-warning-actions"><button type="button" class="secondary-button" data-cancel>Ahora no</button><button type="button" class="primary-button" data-confirm>Activar efecto</button></div>';document.body.appendChild(dialog);const cleanup=()=>dialog.remove();dialog.querySelector("[data-cancel]").addEventListener("click",()=>dialog.close());dialog.querySelector("[data-confirm]").addEventListener("click",()=>{dialog.close();if(action==="ambient")setAmbientEnabled(true);else setAtmosphereEnabled(true);});dialog.addEventListener("close",cleanup,{once:true});dialog.addEventListener("click",event=>{if(event.target===dialog)dialog.close();});dialog.showModal();}
function setAmbientEnabled(value){ambientEnabled=value;try{localStorage.setItem("astralworld-ambient-light",ambientEnabled?"1":"0");}catch(error){}applyAmbientLight();const label=document.querySelector(".ambient-state");if(label)label.textContent=ambientEnabled?"Activado":"Desactivado";document.querySelectorAll('[data-action="ambient"]').forEach(toggle=>{toggle.classList.toggle("active",ambientEnabled);toggle.setAttribute("aria-checked",String(ambientEnabled));toggle.setAttribute("aria-pressed",String(ambientEnabled));toggle.setAttribute("aria-label",ambientEnabled?"Desactivar Ambient light":"Activar Ambient light");});}
function setAtmosphereEnabled(value){atmosphereEnabled=value;try{localStorage.setItem("astralworld-video-atmosphere",atmosphereEnabled?"1":"0");}catch(error){}applyAmbientLight();document.querySelectorAll('[data-action="atmosphere"]').forEach(toggle=>{toggle.classList.toggle("active",atmosphereEnabled);toggle.setAttribute("aria-checked",String(atmosphereEnabled));});}
function act(action){const video=document.getElementById("mainVideo");if(action==="ambient"){if(!ambientEnabled){confirmPerformanceEffect("ambient");return;}setAmbientEnabled(false);return;}if(action==="atmosphere"){if(!atmosphereEnabled){confirmPerformanceEffect("atmosphere");return;}setAtmosphereEnabled(false);return;}if(action==="install"){installAstralWorld();return;}if(action==="font"){openFontPicker();return;}if(action==="resetFont"){resetSubtitleFont();return;}if(action==="collections"){openCollectionsPage();return;}if(action==="add")picker.click();if(action==="folder")readDeviceFolder();if(action==="back"){if(document.fullscreenElement)document.exitFullscreen();go(state.lastPage||"library");}if(action==="toggle"&&video){if(video.paused)video.play().catch(()=>{});else video.pause();}if(action==="expand")expand();if(action==="seekBack"&&video)seekBy(-10);if(action==="seekForward"&&video)seekBy(10);if(action==="exitFullscreen"&&document.fullscreenElement)document.exitFullscreen().catch(console.warn);if(action==="closeMini"){const mini=document.getElementById("miniPlayer");if(mini)mini.classList.add("is-closing");if(miniEffectsFrame){cancelAnimationFrame(miniEffectsFrame);miniEffectsFrame=0;}if(state.currentVideo&&persistentVideo){state.currentVideo.progress=persistentVideo.currentTime||state.currentVideo.progress;saveVideo(state.currentVideo).catch(console.warn);}if(persistentVideo){persistentVideo.pause();persistentVideo.currentTime=0;persistentVideo.removeAttribute("src");persistentVideo.load();persistentVideo.remove();}if(activeUrl)URL.revokeObjectURL(activeUrl);activeUrl=null;persistentVideo=null;state.currentVideo=null;setTimeout(()=>mini?.remove(),230);}if(action==="menu")showPlayerMenu();if(action==="editInfo")editCurrentInfo();if(action==="subtitles"){openSubtitlePicker();return;}if(action==="lock"){toggleScreenLock();return;}if(action==="screenshot"){captureFrame();return;}if(action==="subtitleStyle"){openSubtitleStyle();return;}if(action==="playbackMode"){cyclePlaybackMode();return;}if(action==="audioMode"){openAudioModeDialog();return;}if(action==="audio")alert("La selección de pistas estará disponible cuando el archivo incluya varias.");if(action==="speed"&&video){openSpeedPicker(video);return;}}
document.addEventListener("fullscreenchange",()=>{applyAmbientLight();const active=!!document.fullscreenElement;const btn=document.getElementById("fullscreenToggle");if(btn){btn.innerHTML=active?svgExitFullscreen:svgExpand;btn.setAttribute("aria-label",active?"Salir de pantalla completa":"Pantalla completa");}if(!active&&screen.orientation&&screen.orientation.unlock)screen.orientation.unlock();});
picker.addEventListener("change",async e=>{await importFiles(e.target.files);picker.value="";});
async function readDeviceFolder(){if(window.showDirectoryPicker){try{const dir=await window.showDirectoryPicker({mode:"read"});const files=[];async function walk(handle,path=""){for await(const entry of handle.values()){const entryPath=path?path+"/"+entry.name:entry.name;if(entry.kind==="directory")await walk(entry,entryPath);else if(entry.kind==="file"){const file=await entry.getFile();if(isVideoFile(file))files.push({file,relativePath:entryPath});}}}await walk(dir);const count=await importFiles(files);if(!count&&!files.length)alert("No se encontraron vídeos en esa carpeta.");return;}catch(err){if(err&&err.name==="AbortError")return;console.warn("No se pudo leer la carpeta",err);}}const fp=document.getElementById("folderPicker");if(fp)fp.click();else alert("Este navegador no permite seleccionar carpetas. Usa Añadir vídeos.");}
const folderPicker=document.getElementById("folderPicker");if(folderPicker)folderPicker.addEventListener("change",async e=>{await importFiles(e.target.files);folderPicker.value="";});
document.getElementById("headerAction").innerHTML=svgSearch;document.getElementById("headerAction").addEventListener("click",()=>{go(state.mode==="local"?"library":"home");const search=document.querySelector('input[type="search"]');if(search){search.focus();search.classList.remove("is-opening");void search.offsetWidth;search.classList.add("is-opening");setTimeout(()=>search.classList.remove("is-opening"),460);}});
try{ambientEnabled=localStorage.getItem("astralworld-ambient-light")==="1";atmosphereEnabled=localStorage.getItem("astralworld-video-atmosphere")==="1";currentTheme=localStorage.getItem("astralworld-theme")||"astral";if(!themeNames[currentTheme])currentTheme="astral";}catch(error){}applyTheme();render();
try{const subtitleSettings=JSON.parse(localStorage.getItem("astralworld-subtitle-style")||"null");if(subtitleSettings)applySubtitleStyle(subtitleSettings);}catch(error){}
libraryReady=restoreLibrary();

let deferredInstallPrompt=null;
window.addEventListener("beforeinstallprompt",event=>{event.preventDefault();deferredInstallPrompt=event;});
window.addEventListener("appinstalled",()=>{deferredInstallPrompt=null;});
async function installAstralWorld(){
  if(deferredInstallPrompt){
    deferredInstallPrompt.prompt();
    await deferredInstallPrompt.userChoice;
    deferredInstallPrompt=null;
    return;
  }
  alert("Si tu navegador permite instalarla, abre el menú ⋮ y elige «Instalar aplicación» o «Añadir a pantalla de inicio». Si esa opción no aparece, comprueba que estés usando la dirección HTTPS publicada.");
}

/* AstralWorld v21 · progreso, colecciones y controles de reproducción */
let playQueue=[];try{playQueue=JSON.parse(localStorage.getItem("astralworld-play-queue")||"[]");if(!Array.isArray(playQueue))playQueue=[];}catch(error){playQueue=[];}
let personalCollections=[];try{personalCollections=JSON.parse(localStorage.getItem("astralworld-collections")||"[]");if(!Array.isArray(personalCollections))personalCollections=[];}catch(error){personalCollections=[];}
function savePlayQueue(){try{localStorage.setItem("astralworld-play-queue",JSON.stringify(playQueue));}catch(error){}}
function saveCollections(){try{localStorage.setItem("astralworld-collections",JSON.stringify(personalCollections));}catch(error){}}
function formatBytes(bytes){if(!bytes)return"No disponible";const units=["B","KB","MB","GB"];let value=bytes,index=0;while(value>=1024&&index<units.length-1){value/=1024;index++;}return value.toFixed(index?1:0)+" "+units[index];}
function resumeChoice(v,done){const dialog=document.createElement("dialog");dialog.className="player-choice-dialog resume-choice-dialog";dialog.innerHTML='<div class="player-choice-head"><span class="eyebrow">ASTRALWORLD</span><h2>¿Continuar viendo?</h2><p>'+esc(v.name)+' · '+time(v.progress)+'</p></div><div class="resume-choice-actions"><button type="button" class="resume-icon-button" data-resume="continue" aria-label="Continuar" title="Continuar"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m8 5 11 7-11 7z"/></svg></button><button type="button" class="resume-icon-button" data-resume="restart" aria-label="Reiniciar" title="Reiniciar"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 11a8 8 0 1 1 2.3 6M4 4v7h7"/></svg></button></div>';document.body.appendChild(dialog);dialog.querySelector('[data-resume="continue"]').addEventListener("click",()=>{dialog.close();done(false);});dialog.querySelector('[data-resume="restart"]').addEventListener("click",()=>{dialog.close();done(true);});dialog.addEventListener("close",()=>dialog.remove(),{once:true});dialog.showModal();}
const originalOpenVideo=openVideo;
openVideo=function(id,options={}){const v=state.videos.find(item=>item.id===id);if(!v)return;if(state.page==="explore"){v.progress=0;v.watched=false;saveVideo(v).catch(console.warn);return originalOpenVideo(id);}if(state.page==="library"&&!options.skipPrompt&&v.progress>5&&v.duration>0&&v.progress<v.duration-10&&!v.watched){resumeChoice(v,restart=>{if(restart){v.progress=0;v.watched=false;saveVideo(v).catch(console.warn);}originalOpenVideo(id);});return;}if(options.skipPrompt){return originalOpenVideo(id);}return originalOpenVideo(id);};
const originalPlayer=player;
player=function(){const v=state.currentVideo;if(!v)return originalPlayer();let html=originalPlayer();html=html.replace('<details class="player-info">','<div class="player-extra-actions"><button class="player-action" data-action="markWatched" type="button"><span class="action-icon">✓</span><span>'+(v.watched?"Marcar como no visto":"Marcar como visto")+'</span></button><button class="player-action" data-action="queueAdd" type="button"><span class="action-icon">＋</span><span>Añadir a cola</span></button><button class="player-action" data-action="queueShow" type="button"><span class="action-icon">☷</span><span>Cola ('+playQueue.length+')</span></button><button class="player-action" data-action="collectionAdd" type="button"><span class="action-icon">▤</span><span>Añadir a colección</span></button></div><details class="player-info">');
html=html.replace('<strong>'+esc(v.fileName||v.file?.name||"No disponible")+'</strong></div><div class="info-line"><span>Formato</span><strong>'+kind(v)+'</strong></div><div class="info-line"><span>Ubicación</span><strong>Este dispositivo</strong></div>',
'<strong>'+esc(v.fileName||v.file?.name||"No disponible")+'</strong></div><div class="info-line"><span>Duración</span><strong>'+time(v.duration)+'</strong></div><div class="info-line"><span>Resolución</span><strong>'+esc(v.resolution||(v.width&&v.height?v.width+" × "+v.height:"No disponible"))+'</strong></div><div class="info-line"><span>Formato</span><strong>'+esc(v.mimeType||"No disponible")+'</strong></div><div class="info-line"><span>Tamaño</span><strong>'+formatBytes(v.size||v.file?.size)+'</strong></div><div class="info-line"><span>Añadido</span><strong>'+formatDate(v.addedAt)+'</strong></div><div class="info-line"><span>Última reproducción</span><strong>'+formatDate(v.lastPlayedAt)+'</strong></div><div class="info-line"><span>Ubicación</span><strong>Este dispositivo</strong></div>');
return html;};
const originalSettings=settings;
settings=function(){let html=originalSettings();return html.replace('<section class="settings-group"><h2>Instalación</h2>','<section class="settings-group"><h2>Reproducción</h2><div class="setting-row"><div><strong>Reproducción automática</strong><p>Al terminar un vídeo, reproduce el siguiente automáticamente.</p></div><button class="setting-toggle '+(localStorage.getItem("astralworld-autoplay")==="1"?"active":"")+'" data-action="autoplay" type="button" role="switch" aria-checked="'+(localStorage.getItem("astralworld-autoplay")==="1")+'"><span></span></button></div><div class="setting-row"><div><strong>Guardar progreso</strong><p>Conserva el minuto exacto aunque cierres AstralWorld.</p></div><span class="tag">Siempre activo</span></div><div class="setting-row"><div><strong>Gestos del reproductor</strong><p>Doble toque para saltar 10 s. Desliza verticalmente: lado izquierdo para brillo y derecho para volumen.</p></div><span class="tag">Activos</span></div></section><section class="settings-group"><h2>Instalación</h2>');};
function collectionDialog(videoId=null){const dialog=document.createElement("dialog");dialog.className="player-choice-dialog";dialog.innerHTML='<div class="player-choice-head"><span class="eyebrow">BIBLIOTECA</span><h2>Colecciones personales</h2><p>Organiza tus vídeos en espacios propios.</p></div><div class="collection-dialog-list">'+(personalCollections.map(c=>'<label class="collection-check"><input type="checkbox" value="'+esc(c.id)+'" '+(videoId&&c.videoIds.includes(videoId)?"checked":"")+'><span>'+esc(c.name)+'</span><small>'+c.videoIds.length+'</small></label>').join("")||'<p class="settings-hint">Todavía no tienes colecciones.</p>')+'</div><div class="collection-dialog-actions"><button class="secondary-button" type="button" data-create-collection>＋ Nueva colección</button><button class="primary-button" type="button" data-save-collections>Guardar</button></div><button class="text-button" type="button" data-close-collections>Cerrar</button>';document.body.appendChild(dialog);dialog.querySelector("[data-create-collection]").addEventListener("click",()=>{const name=prompt("Nombre de la nueva colección");if(!name?.trim())return;const id="collection-"+Date.now();personalCollections.push({id,name:name.trim().slice(0,40),videoIds:[]});saveCollections();dialog.close();collectionDialog(videoId);});dialog.querySelector("[data-save-collections]").addEventListener("click",()=>{if(videoId){personalCollections.forEach(c=>{c.videoIds=c.videoIds.filter(id=>id!==videoId);});dialog.querySelectorAll('input[type="checkbox"]:checked').forEach(input=>personalCollections.find(c=>c.id===input.value)?.videoIds.push(videoId));saveCollections();}dialog.close();});dialog.querySelector("[data-close-collections]").addEventListener("click",()=>dialog.close());dialog.addEventListener("close",()=>dialog.remove(),{once:true});dialog.showModal();}
function showPlayQueue(){const dialog=document.createElement("dialog");dialog.className="player-choice-dialog";dialog.innerHTML='<div class="player-choice-head"><span class="eyebrow">REPRODUCCIÓN</span><h2>Cola de reproducción</h2><p>El siguiente vídeo se reproducirá al terminar el actual.</p></div><div class="queue-list">'+(playQueue.map((id,index)=>{const v=state.videos.find(x=>x.id===id);return v?'<div class="queue-row"><button type="button" data-queue-play="'+id+'">'+(index+1)+'. '+esc(v.name)+'</button><button type="button" data-queue-remove="'+id+'" aria-label="Quitar de la cola">×</button></div>':"";}).join("")||'<p class="settings-hint">La cola está vacía.</p>')+'</div><button class="secondary-button" type="button" data-queue-close>Cerrar</button>';document.body.appendChild(dialog);dialog.querySelectorAll("[data-queue-play]").forEach(b=>b.addEventListener("click",()=>{const id=b.dataset.queuePlay;playQueue=playQueue.filter(x=>x!==id);savePlayQueue();dialog.close();openVideo(id,{skipPrompt:true});}));dialog.querySelectorAll("[data-queue-remove]").forEach(b=>b.addEventListener("click",()=>{playQueue=playQueue.filter(x=>x!==b.dataset.queueRemove);savePlayQueue();dialog.close();showPlayQueue();}));dialog.querySelector("[data-queue-close]").addEventListener("click",()=>dialog.close());dialog.addEventListener("close",()=>dialog.remove(),{once:true});dialog.showModal();}
function addCurrentToQueue(){const id=state.currentVideo?.id;if(!id)return;if(!playQueue.includes(id)){playQueue.push(id);savePlayQueue();}alert("Vídeo añadido a la cola.");}
const originalAct=act;
act=function(action){if(action==="audioMode"){openAudioModeDialog();return;}if(action==="autoplay"){const enabled=localStorage.getItem("astralworld-autoplay")==="1";localStorage.setItem("astralworld-autoplay",enabled?"0":"1");render();return;}if(action==="markWatched"){const v=state.currentVideo;if(v){v.watched=!v.watched;v.progress=v.watched?(v.duration||persistentVideo?.duration||0):0;saveVideo(v).catch(console.warn);render();}return;}if(action==="queueAdd"){addCurrentToQueue();return;}if(action==="queueShow"){showPlayQueue();return;}if(action==="collectionAdd"){collectionDialog(state.currentVideo?.id);return;}return originalAct(action);};
function openCollectionsPage(){const cards=personalCollections.map(c=>'<article class="collection-card"><div><strong>'+esc(c.name)+'</strong><small>'+c.videoIds.filter(id=>state.videos.some(v=>v.id===id)).length+' vídeos</small></div><button class="secondary-button" data-collection-open="'+esc(c.id)+'" type="button">Abrir</button><button class="icon-button" data-collection-edit="'+esc(c.id)+'" type="button" aria-label="Editar colección">⋯</button></article>').join("");content.innerHTML='<button class="text-button" data-page="library" type="button">'+svgArrowLeft+' Biblioteca</button><span class="eyebrow">ORGANIZA TU UNIVERSO</span><h1>Colecciones</h1><p class="page-intro">Agrupa tus vídeos como quieras.</p><button class="primary-button" data-new-collection type="button">＋ Crear colección</button><div class="collection-list">'+(cards||'<p class="settings-hint">Crea tu primera colección para organizar tus vídeos.</p>')+'</div>';content.querySelector("[data-new-collection]").addEventListener("click",()=>collectionDialog());content.querySelectorAll("[data-collection-open]").forEach(b=>b.addEventListener("click",()=>{const c=personalCollections.find(x=>x.id===b.dataset.collectionOpen);if(!c)return;const items=c.videoIds.map(id=>state.videos.find(v=>v.id===id)).filter(Boolean);content.innerHTML='<button class="text-button" data-collections-back>← Colecciones</button><h1>'+esc(c.name)+'</h1>'+list(items);content.querySelector("[data-collections-back]").addEventListener("click",openCollectionsPage);content.querySelectorAll("[data-video]").forEach(x=>x.addEventListener("click",()=>openVideo(x.dataset.video,{skipPrompt:true})));}));content.querySelectorAll("[data-collection-edit]").forEach(b=>b.addEventListener("click",()=>{const c=personalCollections.find(x=>x.id===b.dataset.collectionEdit);if(c&&confirm('¿Eliminar la colección "'+c.name+'"? Los vídeos no se borrarán.')){personalCollections=personalCollections.filter(x=>x.id!==c.id);saveCollections();openCollectionsPage();}}));}


const originalSetupPlayer=setupPlayer;
setupPlayer=function(){originalSetupPlayer();const stage=document.getElementById("videoStage"),video=persistentVideo;if(!stage||!video||stage.dataset.verticalGestures==="1")return;stage.dataset.verticalGestures="1";let start=null;let indicatorTimer=0;const showGesture=(label)=>{let el=stage.querySelector(".gesture-indicator");if(!el){el=document.createElement("div");el.className="gesture-indicator";stage.appendChild(el);}el.textContent=label;el.classList.add("visible");clearTimeout(indicatorTimer);indicatorTimer=setTimeout(()=>el.classList.remove("visible"),850);};stage.addEventListener("pointerdown",event=>{if(event.target.closest("button,input"))return;start={x:event.clientX,y:event.clientY,id:event.pointerId};},{passive:true});stage.addEventListener("pointerup",event=>{if(!start||start.id!==event.pointerId)return;const dx=event.clientX-start.x,dy=event.clientY-start.y;start=null;if(Math.abs(dy)<34||Math.abs(dy)<Math.abs(dx)*1.25)return;const rect=stage.getBoundingClientRect(),side=(event.clientX-rect.left)/rect.width<.5?"left":"right";if(side==="right"){const volume=Math.max(0,Math.min(1,(video.volume||0)+ (dy<0?.08:-.08)));video.volume=volume;try{localStorage.setItem("astralworld-player-volume",String(volume));}catch(error){}showGesture("Volumen "+Math.round(volume*100)+"%");}else{let brightness=Number(stage.dataset.brightness||1);brightness=Math.max(.35,Math.min(1.5,brightness+(dy<0?.08:-.08)));stage.dataset.brightness=String(brightness);video.style.filter="brightness("+brightness+")";try{localStorage.setItem("astralworld-player-brightness",String(brightness));}catch(error){}showGesture("Brillo "+Math.round(brightness*100)+"%");}stage._suppressClickUntil=Date.now()+400;},{passive:true});try{const volume=Number(localStorage.getItem("astralworld-player-volume"));if(Number.isFinite(volume)&&volume>0.01&&volume<=1)video.volume=volume;else if(!Number.isFinite(volume)||volume<=0.01)video.volume=.85;video.muted=false;const brightness=Number(localStorage.getItem("astralworld-player-brightness"));if(Number.isFinite(brightness)&&brightness>=.35&&brightness<=1.5){stage.dataset.brightness=String(brightness);video.style.filter="brightness("+brightness+")";}}catch(error){}};

function addVideoToQueue(id){if(!state.videos.some(v=>v.id===id))return;if(!playQueue.includes(id))playQueue.push(id);savePlayQueue();const button=document.querySelector('[data-queue-video="'+CSS.escape(id)+'"]');if(button){button.classList.add("queued");button.setAttribute("aria-label","Ya está en la cola");} } const originalBindForQueue=bind;bind=function(){originalBindForQueue();content.querySelectorAll("[data-queue-video]").forEach(button=>button.addEventListener("click",event=>{event.preventDefault();event.stopPropagation();addVideoToQueue(button.dataset.queueVideo);}));};
document.addEventListener("pagehide",()=>{if(state.currentVideo&&persistentVideo){state.currentVideo.progress=persistentVideo.currentTime||state.currentVideo.progress;state.currentVideo.duration=persistentVideo.duration||state.currentVideo.duration;saveVideo(state.currentVideo).catch(()=>{});}});
document.addEventListener("visibilitychange",()=>{if(document.hidden&&ambientFrame){cancelAnimationFrame(ambientFrame);ambientFrame=0;}else if(!document.hidden&&(ambientEnabled||atmosphereEnabled)&&document.getElementById("videoStage"))applyAmbientLight();});
if("serviceWorker"in navigator&&location.protocol.startsWith("http")){
  window.addEventListener("load",async()=>{
    try{
      const registration=await navigator.serviceWorker.register("./service-worker.js",{updateViaCache:"none"});
      registration.update().catch(()=>{});
      const hadController=!!navigator.serviceWorker.controller;
      let reloaded=false;
      navigator.serviceWorker.addEventListener("controllerchange",()=>{
        if(hadController&&!reloaded){reloaded=true;window.location.reload();}
      });
      document.addEventListener("visibilitychange",()=>{
        if(document.visibilityState==="visible")registration.update().catch(()=>{});
      });
    }catch(error){console.warn("No se pudo activar el modo PWA:",error);}
  });
}